-- Create roles if they don't exist
INSERT INTO m_role (id, name, description, created_date, created_by, last_modified_date, last_modified_by)
SELECT * FROM (
    VALUES 
        (uuid_generate_v4(), 'Super Admin', 'Full system access', NOW(), 1, NOW(), 1),
        (uuid_generate_v4(), 'Branch Manager', 'Branch level management access', NOW(), 1, NOW(), 1),
        (uuid_generate_v4(), 'Loan Officer', 'Loan processing and approval', NOW(), 1, NOW(), 1),
        (uuid_generate_v4(), 'Teller', 'Cash transactions and basic operations', NOW(), 1, NOW(), 1),
        (uuid_generate_v4(), 'Field Officer', 'Field operations and client visits', NOW(), 1, NOW(), 1),
        (uuid_generate_v4(), 'Self Service User', 'Client self-service access', NOW(), 1, NOW(), 1)
) AS roles(id, name, description, created_date, created_by, last_modified_date, last_modified_by)
WHERE NOT EXISTS (SELECT 1 FROM m_role WHERE name = roles.name);

-- Assign roles to users
INSERT INTO m_appuser_role (appuser_id, role_id)
SELECT u.id, r.id
FROM m_appuser u
CROSS JOIN m_role r
WHERE (u.username = 'admin' AND r.name = 'Super Admin')
   OR (u.username = 'manager.pos' AND r.name = 'Branch Manager')
   OR (u.username = 'loan.officer' AND r.name = 'Loan Officer')
   OR (u.username = 'teller.chag' AND r.name = 'Teller')
   OR (u.username = 'field.officer' AND r.name = 'Field Officer')
   OR (u.username = 'client.demo' AND r.name = 'Self Service User')
ON CONFLICT DO NOTHING;

-- Link staff users to offices
UPDATE m_staff 
SET userid = u.id
FROM m_appuser u
WHERE (u.username = 'manager.pos' AND m_staff.display_name = 'Maria Rodriguez')
   OR (u.username = 'loan.officer' AND m_staff.display_name = 'John Mohammed')
   OR (u.username = 'teller.chag' AND m_staff.display_name = 'Priya Singh')
   OR (u.username = 'field.officer' AND m_staff.display_name = 'David Williams');

-- Link self-service user to a client
UPDATE m_client
SET userid = u.id
FROM m_appuser u
WHERE u.username = 'client.demo'
AND m_client.display_name = 'Sarah Thompson';

-- Grant permissions to roles
-- Super Admin gets all permissions
INSERT INTO m_role_permission (role_id, permission_id)
SELECT r.id, p.id
FROM m_role r
CROSS JOIN m_permission p
WHERE r.name = 'Super Admin'
ON CONFLICT DO NOTHING;

-- Branch Manager permissions
INSERT INTO m_role_permission (role_id, permission_id)
SELECT r.id, p.id
FROM m_role r
CROSS JOIN m_permission p
WHERE r.name = 'Branch Manager'
AND p.code IN (
    'READ_CLIENT', 'CREATE_CLIENT', 'UPDATE_CLIENT',
    'READ_LOAN', 'CREATE_LOAN', 'APPROVE_LOAN',
    'READ_SAVINGSACCOUNT', 'CREATE_SAVINGSACCOUNT', 'APPROVE_SAVINGSACCOUNT',
    'READ_STAFF', 'CREATE_STAFF', 'UPDATE_STAFF',
    'READ_OFFICE', 'READ_REPORT', 'RUN_REPORT'
)
ON CONFLICT DO NOTHING;

-- Loan Officer permissions
INSERT INTO m_role_permission (role_id, permission_id)
SELECT r.id, p.id
FROM m_role r
CROSS JOIN m_permission p
WHERE r.name = 'Loan Officer'
AND p.code IN (
    'READ_CLIENT', 'CREATE_CLIENT', 'UPDATE_CLIENT',
    'READ_LOAN', 'CREATE_LOAN', 'UPDATE_LOAN',
    'DISBURSE_LOAN', 'REPAYMENT_LOAN',
    'READ_SAVINGSACCOUNT', 'READ_REPORT'
)
ON CONFLICT DO NOTHING;

-- Teller permissions
INSERT INTO m_role_permission (role_id, permission_id)
SELECT r.id, p.id
FROM m_role r
CROSS JOIN m_permission p
WHERE r.name = 'Teller'
AND p.code IN (
    'READ_CLIENT', 
    'READ_SAVINGSACCOUNT', 'DEPOSIT_SAVINGSACCOUNT', 'WITHDRAWAL_SAVINGSACCOUNT',
    'READ_LOAN', 'REPAYMENT_LOAN',
    'READ_TRANSACTION', 'CREATE_TRANSACTION'
)
ON CONFLICT DO NOTHING;

-- Self Service User permissions
INSERT INTO m_role_permission (role_id, permission_id)
SELECT r.id, p.id
FROM m_role r
CROSS JOIN m_permission p
WHERE r.name = 'Self Service User'
AND p.code IN (
    'READ_CLIENT_SELF',
    'READ_LOAN_SELF',
    'READ_SAVINGSACCOUNT_SELF',
    'READ_TRANSACTION_SELF'
)
ON CONFLICT DO NOTHING;

