COMMIT;

-- Display created users
SELECT 
    'Demo Users Created:' as info
UNION ALL
SELECT 
    '==================' as info
UNION ALL
SELECT 
    'Username: ' || username || ' | Password: Admin@123 | Role: ' || r.name
FROM m_appuser u
LEFT JOIN m_appuser_role ur ON u.id = ur.appuser_id
LEFT JOIN m_role r ON ur.role_id = r.id
WHERE u.username IN ('admin', 'manager.pos', 'loan.officer', 'teller.chag', 'field.officer', 'client.demo')
ORDER BY 1;